&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Company focal point for external suppliers.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559740&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Mentor and provide technical guidance for design challenges in the team.&lt;/span&gt;&lt;/li&gt;
